import os,glob,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def blocks(g):
    B=[]; seen=set()
    for i in range(len(g)):
        for j in range(len(g[0])):
            c=g[i][j]
            if c and (i,j) not in seen:
                # check 3x3
                if i+2<len(g) and j+2<len(g[0]) and all(g[i+a][j+b]==c for a in range(3) for b in range(3)):
                    B.append((c,i,j))
                    for a in range(3):
                        for b in range(3): seen.add((i+a,j+b))
    return B

def transform(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    B=blocks(g)
    lines=[]  # (color, axis, idx)
    for c,i,j in B:
        lines.append((c,0,i+1)); lines.append((c,1,j+1))
    for c,a,idx in lines:
        for x in range(h if a==0 else w):
            i,j=(idx,x) if a==0 else (x,idx)
            g[i][j]=c
    # intersections of different-colored lines -> 0
    for c1,a1,i1 in lines:
        for c2,a2,i2 in lines:
            if c1!=c2 and a1!=a2:
                r = i1 if a1==0 else i2
                cc = i2 if a1==0 else i1
                g[r][cc]=0
    for c,i,j in B:
        for a in range(3):
            for b in range(3): g[i+a][j+b]=c
    return g

